companies = list_companies({})
by_domain = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    return list_contacts({ page: page }).items
}
all = fold acc = first.items for page_items in remaining {
    return acc + page_items
}
results = for contact in all {
    needs_company = (contact.company == null or contact.company == "") and contact.email != null
    domain = if needs_company {
        parts = text.split(contact.email, "@")
        return parts[1] if list.length(parts) > 1 else null
    } else {
        return null
    }
    new_company = by_domain[domain] if domain != null and domain in by_domain else null
    fill_company = new_company != null

    phone = contact.phone if contact.phone != null else ""
    already_valid = regex.test(phone, "^\\+1\\d{10}$")
    digits = regex.replace(phone, "[^0-9]", "")
    fixed_phone = if already_valid {
        return null
    } else if text.starts_with(digits, "1") and text.length(digits) == 11 {
        return "+" + digits
    } else if text.length(digits) == 10 {
        return "+1" + digits
    } else if text.length(digits) > 0 {
        return "+1" + text.slice(digits, text.length(digits) - 10) if text.length(digits) > 10 else "+1" + digits
    } else {
        return null
    }
    fix_phone = fixed_phone != null

    updated = if fix_phone and fill_company {
        return update_contact({ id: contact.id, phone: fixed_phone, company: new_company })
    } else if fix_phone {
        return update_contact({ id: contact.id, phone: fixed_phone })
    } else if fill_company {
        return update_contact({ id: contact.id, company: new_company })
    } else {
        return null
    }
    return {
        phone_fixed: fix_phone,
        company_filled: fill_company
    }
}
phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}
submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submit }

